<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Members | Net-Works</title>
    <style>
        :root{--ink:#17233c;--muted:#6f7c93;--line:#e1e8f1;--blue:#397ef6;--navy:#172b4d;--bg:#f4f7fb;--shadow:0 8px 25px rgba(32,52,84,.07)}
        *{box-sizing:border-box}body{margin:0;background:linear-gradient(180deg,#edf3ff 0,#f8f5ff 48%,#f4f7fb 100%);color:var(--ink);font-family:Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.topbar{display:flex;align-items:center;justify-content:space-between;gap:16px;min-height:68px;padding:10px max(20px,calc((100vw - 1080px)/2));border-bottom:1px solid #dbe5f5;background:#fff}.brand img{display:block;max-width:155px;max-height:44px}.back{display:inline-flex;align-items:center;min-height:42px;padding:0 15px;border-radius:9px;background:linear-gradient(135deg,#172b4d,#294f91);color:#fff;text-decoration:none;font-size:13px;font-weight:800;box-shadow:0 7px 18px rgba(23,43,77,.2)}.page{width:min(1080px,calc(100% - 32px));margin:24px auto 60px}.directory-intro{position:relative;overflow:hidden;margin-bottom:16px;padding:22px;border-radius:20px;background:linear-gradient(125deg,#173465,#397ef6 62%,#7257df);box-shadow:0 14px 34px rgba(42,88,174,.22)}.directory-intro:after{content:"";position:absolute;right:-55px;top:-70px;width:180px;height:180px;border-radius:50%;background:rgba(255,255,255,.11)}.heading{position:relative;z-index:1;display:flex;align-items:end;justify-content:space-between;gap:14px;margin-bottom:14px}.heading h1{margin:0;color:#fff;font-size:28px;letter-spacing:-.5px}.heading p{margin:5px 0 0;color:#dce9ff;font-size:13px}.count{padding:6px 10px;border-radius:999px;background:rgba(255,255,255,.16);color:#fff;font-size:11px;font-weight:800}.search{position:relative;z-index:1;display:flex;gap:9px;padding:9px;border:1px solid rgba(255,255,255,.35);border-radius:13px;background:rgba(255,255,255,.95);box-shadow:var(--shadow)}.search input{min-width:0;min-height:44px;flex:1;padding:10px 13px;border:1px solid #d6e0ed;border-radius:9px;color:var(--ink);font:inherit;font-size:14px;outline:none}.search input:focus{border-color:var(--blue);box-shadow:0 0 0 3px rgba(57,126,246,.1)}.search button{min-height:44px;padding:0 20px;border:0;border-radius:9px;background:linear-gradient(135deg,#397ef6,#6b52dc);color:#fff;font:inherit;font-size:13px;font-weight:800;cursor:pointer}.members{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:11px}.member{--accent:#397ef6;--soft:#edf4ff;display:grid;grid-template-columns:48px minmax(0,1fr) auto 142px;align-items:center;gap:12px;padding:14px;border:1px solid color-mix(in srgb,var(--accent) 25%,#e1e8f1);border-top:4px solid var(--accent);border-radius:14px;background:#fff;box-shadow:var(--shadow)}.member:nth-child(4n+2){--accent:#14a47c;--soft:#e6f8f2}.member:nth-child(4n+3){--accent:#8a5ce6;--soft:#f1ebff}.member:nth-child(4n+4){--accent:#ef843b;--soft:#fff0e5}.avatar{display:grid;place-items:center;width:48px;height:48px;border-radius:13px;background:var(--soft);color:var(--accent);font-size:14px;font-weight:800}.member-copy{min-width:0}.member h2{overflow:hidden;margin:0;color:var(--ink);font-size:15px;line-height:1.3;text-overflow:ellipsis;white-space:nowrap}.businesses{overflow:hidden;margin-top:4px;color:var(--muted);font-size:11px;line-height:1.35;text-overflow:ellipsis;white-space:nowrap}.phone{display:inline-flex;align-items:center;min-height:36px;padding:0 10px;border-radius:9px;background:var(--soft);color:var(--accent);text-decoration:none;font-size:11px;font-weight:800;white-space:nowrap}.empty{grid-column:1/-1;padding:45px 20px;border:1px dashed #cbd7e6;border-radius:14px;background:#fff;color:var(--muted);text-align:center}.pager{display:flex;align-items:center;justify-content:center;gap:9px;margin-top:20px}.pager a,.pager span{display:inline-flex;align-items:center;min-height:40px;padding:0 14px;border:1px solid var(--line);border-radius:9px;background:#fff;color:#43536b;text-decoration:none;font-size:12px;font-weight:700}.pager .disabled{color:#a4afbe;background:#f3f5f8}
        @media(max-width:700px){.page{width:min(100% - 24px,1080px);margin-top:18px}.directory-intro{padding:18px}.heading{align-items:flex-start;flex-direction:column;gap:8px}.heading h1{font-size:24px}.members{grid-template-columns:1fr}.member{grid-template-columns:44px minmax(0,1fr) auto 142px;padding:12px}.avatar{width:44px;height:44px}.search button{padding:0 14px}}
        @media(max-width:420px){.topbar{padding:9px 14px}.brand img{max-width:125px}.member{grid-template-columns:42px minmax(0,1fr) 132px}.phone{grid-column:2;justify-self:start;min-height:30px;margin-top:-3px}.search{flex-wrap:wrap}.search input,.search button{flex:1 1 100%;font-size:16px}.search button{font-size:13px}}
        @media(max-width:360px){.member{grid-template-columns:42px minmax(0,1fr)}}

/* compact intro: title + count on one line, search on one row */
.directory-intro{padding:14px 16px;border-radius:18px}
.directory-intro:after{width:120px;height:120px;right:-40px;top:-50px}
.directory-intro .heading{flex-direction:row;align-items:center;justify-content:space-between;gap:10px;margin-bottom:10px}
.directory-intro .heading h1{font-size:20px;letter-spacing:-.3px}
.directory-intro .search{flex-wrap:nowrap;gap:8px;padding:6px;border-radius:12px}
.directory-intro .search input{flex:1 1 auto;min-height:42px}
.directory-intro .search button{flex:0 0 auto;min-height:42px;padding:0 16px}

/* colourful member cards: name in a coloured band, business + contact on a white sheet */
.members .member{display:block;padding:0;border:0;border-radius:20px;overflow:hidden;background:linear-gradient(135deg,color-mix(in srgb,var(--accent) 62%,#0b1a3a),var(--accent));box-shadow:0 12px 26px color-mix(in srgb,var(--accent) 22%,transparent)}
.m-band{display:flex;align-items:center;gap:12px;padding:14px 16px 32px}
.members .member .avatar{flex:0 0 44px;width:44px;height:44px;border-radius:13px;background:rgba(255,255,255,.18);border:1px solid rgba(255,255,255,.3);color:#fff;font-size:15px}
.members .member h2{flex:1;min-width:0;color:#fff;font-size:17px}
.m-sheet{position:relative;display:flex;flex-wrap:wrap;align-items:center;gap:10px 12px;margin-top:-18px;padding:16px;border-radius:18px 18px 0 0;background:#fff}
.m-sheet .businesses{display:flex;align-items:center;gap:8px;flex:1 1 100%;min-width:0;color:var(--ink);font-size:14px;font-weight:600}
.m-sheet .businesses span{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.m-sheet .businesses svg{flex:0 0 18px;width:18px;height:18px;fill:var(--accent)}
.m-sheet .phone{grid-column:auto;margin:0;min-height:38px;padding:0 14px;border-radius:999px;font-size:13px}
.activity-button{min-height:38px;margin-left:auto;padding:0 13px;border:1px solid color-mix(in srgb,var(--accent) 35%,#dce5f1);border-radius:999px;background:#fff;color:var(--accent);font:inherit;font-size:11px;font-weight:800;cursor:pointer}.activity-button:hover{background:var(--soft)}

/* activity modal */
.activity-modal{width:min(420px,calc(100% - 24px));max-width:none;max-height:calc(100vh - 32px);margin:auto;padding:0;border:0;border-radius:22px;background:#f6f8fc;box-shadow:0 26px 80px rgba(15,30,55,.32)}.activity-modal[open]{display:flex;flex-direction:column}.activity-modal::backdrop{background:rgba(10,22,43,.58);backdrop-filter:blur(2px)}.drawer-head{display:flex;align-items:center;gap:12px;padding:20px;background:linear-gradient(135deg,#173465,#397ef6 65%,#7056dc);color:#fff}.drawer-head-copy{min-width:0;flex:1}.drawer-kicker{display:block;color:#cfe0ff;font-size:9px;font-weight:800;letter-spacing:.1em;text-transform:uppercase}.drawer-head h2{overflow:hidden;margin:4px 0 0;font-size:21px;text-overflow:ellipsis;white-space:nowrap}.drawer-close{display:grid;place-items:center;width:40px;height:40px;flex:0 0 40px;border:1px solid rgba(255,255,255,.35);border-radius:50%;background:rgba(255,255,255,.14);color:#fff;font-size:22px;cursor:pointer}.drawer-body{overflow-y:auto;padding:18px}.period-tabs{display:grid;grid-template-columns:1fr 1fr;gap:5px;padding:4px;border-radius:12px;background:#e8edf5}.period-tab{min-height:40px;border:0;border-radius:9px;background:transparent;color:#65748a;font:inherit;font-size:12px;font-weight:800;cursor:pointer}.period-tab.active{background:#fff;color:#275fbd;box-shadow:0 3px 10px rgba(36,57,90,.1)}.score-card{display:flex;align-items:center;gap:14px;margin-top:14px;padding:16px;border-radius:16px;background:linear-gradient(135deg,#172b4d,#315eaa);color:#fff}.score-orb{display:grid;place-items:center;width:62px;height:62px;flex:0 0 62px;border:4px solid rgba(255,255,255,.2);border-radius:50%;background:#397ef6;font-size:22px;font-weight:900}.score-copy strong{display:block;font-size:16px}.score-copy span{display:block;margin-top:4px;color:#d5e4ff;font-size:11px;line-height:1.4}.achievement-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:14px}.achievement{padding:14px;border:1px solid #e0e7f1;border-radius:14px;background:#fff;box-shadow:0 6px 18px rgba(35,53,82,.05)}.achievement-icon{display:grid;place-items:center;width:34px;height:34px;border-radius:10px;background:var(--tile-soft);color:var(--tile);font-size:17px}.achievement strong{display:block;margin-top:10px;color:var(--tile);font-size:24px;line-height:1}.achievement span{display:block;margin-top:4px;color:#273750;font-size:12px;font-weight:800}.achievement small{display:block;margin-top:3px;color:#8290a4;font-size:9px}.achievement.meetings{--tile:#397ef6;--tile-soft:#edf4ff}.achievement.references{--tile:#8258dd;--tile-soft:#f1ebff}.achievement.network{--tile:#159b72;--tile-soft:#e8f8f2}.achievement.reviews{--tile:#e57a2d;--tile-soft:#fff0e5}.drawer-note{margin:14px 2px 0;color:#7c899c;font-size:10px;line-height:1.5}
</style>
</head>
<body>
<header class="topbar"><a class="brand" href="{{ route('dashboard.index') }}">@include('Member.partials.site-logo')</a><a class="back" href="{{ route('dashboard.index') }}">← Dashboard</a></header>
<main class="page">
    <section class="directory-intro"><div class="heading"><div><h1>Members</h1></div><span class="count">{{ $members->total() }} {{ Str::plural('member', $members->total()) }}</span></div>
    <form class="search" method="GET" action="{{ route('member.members.index') }}"><input name="search" value="{{ $search }}" placeholder="Name, phone or business" aria-label="Search members"><button type="submit">Search</button></form></section>
    <section class="members" aria-label="Member directory">
        @forelse($members as $networkMember)
            @php
                $name = $networkMember->um_name;
                $initials = collect(explode(' ', $name))->filter()->take(2)->map(fn ($word) => Str::upper(Str::substr($word, 0, 1)))->implode('');
                $businessNames = $networkMember->companies->pluck('details.cmpd_name')->filter()->implode(', ');
            @endphp
            <article class="member"><div class="m-band"><div class="avatar" aria-hidden="true">{{ $initials ?: 'NW' }}</div><h2>{{ $name }}</h2></div><div class="m-sheet"><div class="businesses"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M10 6V4a2 2 0 0 1 2-2 2 2 0 0 1 2 2v2h6a2 2 0 0 1 2 2v4H2V8a2 2 0 0 1 2-2Zm2-2v2V4ZM2 14h8v2h4v-2h8v4a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2Z"/></svg><span>{{ $businessNames ?: 'Business details not added' }}</span></div>@if($networkMember->um_mobile_no)<a class="phone" href="tel:{{ preg_replace('/[^0-9+]/', '', $networkMember->um_mobile_no) }}">☎ {{ $networkMember->um_mobile_no }}</a>@else<span class="phone">No phone</span>@endif<button class="activity-button" type="button" data-activity-name="{{ $name }}" data-activity-stats='@json($networkMember->activity_stats)'>View activity →</button></div></article>
        @empty
            <div class="empty"><strong>No members found.</strong><div>Try a different name, phone number or business.</div></div>
        @endforelse
    </section>
    @if($members->hasPages())<nav class="pager" aria-label="Member pages">@if($members->onFirstPage())<span class="disabled">← Previous</span>@else<a href="{{ $members->previousPageUrl() }}">← Previous</a>@endif <span>Page {{ $members->currentPage() }} of {{ $members->lastPage() }}</span> @if($members->hasMorePages())<a href="{{ $members->nextPageUrl() }}">Next →</a>@else<span class="disabled">Next →</span>@endif</nav>@endif
</main>
<dialog class="activity-modal" id="activityDrawer"><div class="drawer-head"><div class="drawer-head-copy"><span class="drawer-kicker">Member achievements</span><h2 id="activityMemberName">Member activity</h2></div><button class="drawer-close" type="button" aria-label="Close activity modal">×</button></div><div class="drawer-body"><div class="period-tabs" role="group" aria-label="Activity period"><button class="period-tab active" type="button" data-period="recent">Last 30 days</button><button class="period-tab" type="button" data-period="all_time">All time</button></div><div class="score-card"><div class="score-orb" id="activityScore">0</div><div class="score-copy"><strong id="activityLevel">Getting started</strong><span>Network points earned from meaningful community participation.</span></div></div><div class="achievement-grid"><article class="achievement meetings"><div class="achievement-icon">◆</div><strong data-stat="meetings">0</strong><span>Meetings</span><small>One-to-one connections</small></article><article class="achievement references"><div class="achievement-icon">↗</div><strong data-stat="references">0</strong><span>References</span><small>Opportunities shared</small></article><article class="achievement network"><div class="achievement-icon">⚡</div><strong data-stat="activity">0</strong><span>Activity</span><small>Business interactions</small></article><article class="achievement reviews"><div class="achievement-icon">★</div><strong data-stat="reviews">0</strong><span>Reviews</span><small>Experiences published</small></article></div><p class="drawer-note">Points are a friendly activity indicator: meetings ×3, references ×4, activity ×1, and reviews ×3.</p></div></dialog>
<script>
const activityDrawer=document.getElementById('activityDrawer'),activityName=document.getElementById('activityMemberName');let selectedStats=null,selectedPeriod='recent';
function renderActivity(){if(!selectedStats)return;const stats=selectedStats[selectedPeriod]||{};document.querySelectorAll('[data-stat]').forEach(node=>node.textContent=stats[node.dataset.stat]||0);const score=(stats.meetings||0)*3+(stats.references||0)*4+(stats.activity||0)+(stats.reviews||0)*3;document.getElementById('activityScore').textContent=score;document.getElementById('activityLevel').textContent=score>=50?'Network champion':score>=20?'Active connector':score>=5?'Rising member':'Getting started'}
document.querySelectorAll('.activity-button').forEach(button=>button.addEventListener('click',()=>{selectedStats=JSON.parse(button.dataset.activityStats);selectedPeriod='recent';activityName.textContent=button.dataset.activityName;document.querySelectorAll('.period-tab').forEach(tab=>tab.classList.toggle('active',tab.dataset.period==='recent'));renderActivity();activityDrawer.showModal()}));
document.querySelectorAll('.period-tab').forEach(tab=>tab.addEventListener('click',()=>{selectedPeriod=tab.dataset.period;document.querySelectorAll('.period-tab').forEach(item=>item.classList.toggle('active',item===tab));renderActivity()}));
document.querySelector('.drawer-close').addEventListener('click',()=>activityDrawer.close());activityDrawer.addEventListener('click',event=>{if(event.target===activityDrawer)activityDrawer.close()});
</script>
</body>
</html>
